"""Writes results/summary_tables.md and results/fold_flags.csv from the Stage6 summary CSVs (no numbers typed by hand)."""
import pandas as pd
from pathlib import Path
R = Path(__file__).resolve().parents[1] / "results"; md = lambda d, i=False: d.to_markdown(index=i)
A = pd.read_csv(R / "alpha_extended.csv"); C = pd.read_csv(R / "Table_consensus_failure.csv"); Rl = pd.read_csv(R / "cohort_relatedness.csv")
S = pd.read_csv(R / "sibling_exclusion.csv"); G = pd.read_csv(R / "sibling_gene_origin.csv")
AL = ["0.0001", "0.001", "0.01", "0.1", "1.0", "10.0", "100.0", "1000.0"]
A["held-out AUC across alpha 1e-4 … 1000 (· = predictions collapsed, SD < 1e-3)"] = A.apply(lambda r: "  ".join(f"{r[f'heldout_AUC_a{a}']:.3f}" + ("·" if r[f"pred_sd_a{a}"] < 1e-3 else "") for a in AL), axis=1)
a1 = A[["task", "heldout", "panel", "chosen_alpha_stage5", "chosen_alpha_stage6", "chosen_status", "chosen_prediction_collapsed", "heldout_AUC_chosen", "CI_low", "CI_high",
        "held-out AUC across alpha 1e-4 … 1000 (· = predictions collapsed, SD < 1e-3)", "heldout_best_alpha", "heldout_plateau_alpha_ge1", "chosen_minus_best", "chosen_minus_alpha10",
        "spearman_inner_vs_heldout", "rand_MLP_median", "prop_random_ge"]]
a2 = A.groupby("task").agg(cells=("panel", "size"), chosen_1000=("chosen_alpha_stage6", lambda x: int((x == 1000).sum())), chosen_100=("chosen_alpha_stage6", lambda x: int((x == 100).sum())),
                           chosen_10=("chosen_alpha_stage6", lambda x: int((x == 10).sum())), chosen_collapsed=("chosen_prediction_collapsed", "sum"),
                           median_chosen_minus_best=("chosen_minus_best", "median"), worst_chosen_minus_best=("chosen_minus_best", "min"),
                           median_chosen_minus_alpha10=("chosen_minus_alpha10", "median"), range_chosen_minus_alpha10=("chosen_minus_alpha10", lambda x: f"{x.min():+.3f} to {x.max():+.3f}"),
                           median_spearman_inner_vs_heldout=("spearman_inner_vs_heldout", "median"))
L = pd.read_csv(R / "alpha_extended_long.csv"); a3 = L.groupby(["task", "alpha"]).agg(median_heldout_AUC=("heldout_AUC", "median"), share_collapsed=("collapsed", "mean")).round(3).unstack(0)
S["cell"] = S.apply(lambda r: f"{r.AUC:.3f} [{r.CI_low:.2f}–{r.CI_high:.2f}] · rand {r.rand_median:.2f} · {r.prop_random_ge:.2f} (Stage5 with sibling: {r.stage5_AUC_with_sibling:.3f})", axis=1)
out = ["# Stage6 summary tables (generated by scripts/tables_stage6.py)", "",
       "## 1a. Alpha: summary per task", "", md(a2.round(3), True), "", "## 1b. Alpha: median held-out AUC per grid point", "", md(a3, True), "",
       "## 1c. Alpha: per fold × panel", "", md(a1), "",
       "## 2. Consensus-selection failure (per task, per fold)", "", md(C), "",
       "## 3a. Cohort relatedness (all pairs, task universe genes)", "", md(Rl.drop(columns=["max_pair"])), ""]
for h in S.heldout.unique():
    out += [f"## 3b. Sibling exclusion: {h} held out, {S[S.heldout == h].excluded_sibling.iloc[0]} removed from training", "",
            "Cell: AUC [95% CI] · random median · proportion of 50 random panels ≥ AUC (Stage5 AUC with the sibling in training)", "",
            md(S[S.heldout == h].pivot(index="panel", columns="method", values="cell")[["LR", "RF", "MLP", "MLP_alpha", "singscore", "DirAvg"]], True), ""]
out += ["## 3c. GSE19439 fold: origin of the Stage5 panel genes (supplementary diagnostic)", "", md(G), ""]
(R / "summary_tables.md").write_text("\n".join(out), encoding="utf-8")
F = pd.DataFrame([dict(task="LTB_vs_CON", heldout="GSE19439", flag="sibling_selection_dependence",
    note="Panel selected with sibling sub-series GSE19444 (same study, London, GPL6947, submitted a day apart) in training. Stage5 panel retrained without GSE19444 keeps "
         "AUC 0.74-0.78; a panel re-selected without GSE19444 drops to 0.55-0.71 (random-panel proportion >= 0.08-0.48). Treat as sibling-dependent, not cross-study generalisation."),
    dict(task="ATB_vs_OD", heldout="GSE83456", flag="input_gene_median_centred",
    note="GSE83456 expression is GEO's per-gene median-centred log values (Clean_rebuild). z-score-based methods unaffected; singscore (within-sample ranks) and absolute-level "
         "relatedness metrics are not comparable for this cohort.")])
F.to_csv(R / "fold_flags.csv", index=False); print("ok")
